/**
 * What this build is — version, commit, build time, build number.
 * Imported by the backend (`/api/build-info`, the OTA check, the mDNS
 * advert) and, through the REST route, by Settings → About.
 *
 * **Nothing here is committed data.** This file used to be generated by a
 * script and checked in, with an npm `prepackage` hook to refresh it. That
 * hook only fires for a script named exactly `package`, and every real
 * build runs `package:mac:signed` / `package:win` / `package:linux` — so
 * v0.1.10 through v0.1.13 all called themselves 0.1.9, and v0.1.15 called
 * itself 0.1.14 and was offered itself as an update.
 *
 * So each field now comes from the place that cannot drift:
 *
 *   - `version` is imported from `package.json` — the same file
 *     electron-builder stamps into the bundle as the app version, so
 *     this and the macOS About panel are one value, in every environment
 *     (packaged, `tsx` dev backend, unit tests) with no step to forget.
 *   - Everything else is stamped by the bundler: `electron.vite.config.ts`
 *     computes it from git at build time and injects it as
 *     `__CODETRELLIS_BUILD__`. Every packaged build goes through
 *     electron-vite, whichever npm script or CI job started it. Running
 *     from source there is no stamp, and `/api/build-info` reads git live.
 *
 * `scripts/verify-build-stamp.js` checks a packaged `app.asar` carries this
 * version and the commit it was built from; `release.sh` and CI run it.
 */
import { version } from '../../package.json';

export interface BuildInfo {
  version: string;
  buildTime: string;       // ISO 8601
  buildNumber: number;     // commit count from HEAD; monotonic
  commit: string;          // full SHA
  commitShort: string;     // 7-char SHA
  branch: string;
  dirty: boolean;          // working tree had uncommitted changes at build
}

export type BuildStamp = Omit<BuildInfo, 'version'>;

// Replaced at bundle time by electron-vite's `define`. Absent (so the
// `typeof` guard holds) wherever the source runs unbundled.
declare const __CODETRELLIS_BUILD__: BuildStamp | undefined;

const UNSTAMPED: BuildStamp = {
  buildTime: '',
  buildNumber: 0,
  commit: '',
  commitShort: '',
  branch: '',
  dirty: false,
};

export const BUILD_INFO: BuildInfo = {
  version,
  ...(typeof __CODETRELLIS_BUILD__ === 'undefined' ? UNSTAMPED : __CODETRELLIS_BUILD__),
};
